export default "import {\n  SceneFlexLayout,\n  SceneFlexItem,\n  SceneQueryRunner,\n  SceneAppPage,\n  EmbeddedScene,\n  SceneAppPageState,\n  PanelBuilders,\n} from '@grafana/scenes';\nimport { DATASOURCE_REF } from '../constants';\nimport { getEmbeddedSceneDefaults } from './utils';\n\nexport function getPanelContextDemoScene(defaults: SceneAppPageState): SceneAppPage {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexItem({\n              height: 400,\n              body: PanelBuilders.timeseries()\n                .setData(getQueryRunnerFor3SeriesWithLabels())\n                .setTitle('Check legend visibility actions, and color change')\n                .setDisplayName('${__field.labels.cluster}')\n                .build(),\n            }),\n            new SceneFlexItem({\n              height: 400,\n              body: PanelBuilders.text().setOption('content', 'from: ${__from:date:iso} to: ${__to:date:iso}').build(),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n\nexport function getQueryRunnerFor3SeriesWithLabels() {\n  return new SceneQueryRunner({\n    datasource: DATASOURCE_REF,\n    queries: [\n      {\n        labels: 'cluster=eu',\n        refId: 'A',\n        scenarioId: 'random_walk',\n        seriesCount: 1,\n      },\n      {\n        hide: false,\n        labels: 'cluster=us',\n        refId: 'B',\n        scenarioId: 'random_walk',\n        seriesCount: 1,\n      },\n      {\n        hide: false,\n        labels: 'cluster=asia',\n        refId: 'C',\n        scenarioId: 'random_walk',\n        seriesCount: 1,\n      },\n    ],\n  });\n}\n";